let kanjiState={view:'list',id:null,q:'',category:'all',source:'all',scope:'all',page:1};
function getKanjiRoute(){return {...kanjiState}}
function resetKanjiRoute(){kanjiState={view:'list',id:null,q:'',category:'all',source:'all',scope:typeof prefs!=='undefined'&&prefs.level==='N4'?'a2':'all',page:1}}
function restoreKanjiRoute(state){resetKanjiRoute();if(!state)return;kanjiState.q=typeof state.q==='string'?state.q.slice(0,100):'';kanjiState.category=kanjiCategories().some(c=>c.id===state.category)?state.category:'all';kanjiState.source='all';kanjiState.scope=['all','a2','a2-b1','custom'].includes(state.scope)?state.scope:kanjiState.scope;kanjiState.page=Math.max(1,Number(state.page)||1);if(kanjiEntries().some(k=>k.id===state.id)){kanjiState.id=state.id;kanjiState.view=state.view==='detail'?'detail':'list'}}
function rememberKanji(){if(page==='Kanji')history.replaceState(appRoute(),'')}
function openKanji(id){if(!kanjiEntries().some(k=>k.id===id))return;stopAudio();kanjiState.view='detail';kanjiState.id=id;pushRoute();updateScreen()}
function kanjiVisibleEntries(){return kanjiEntries().filter(k=>kanjiState.scope==='all'||k.scope===kanjiState.scope||k.source.id==='custom')}
function kanjiLabel(id){return kanjiCategories().find(c=>c.id===id)?.name||'Semua kategori'}
function kanjiSearchChange(value){kanjiState.q=value.slice(0,100);kanjiState.page=1;refreshKanjiResults();rememberKanji()}
function kanjiFilter(key,value){kanjiState[key]=value;kanjiState.page=1;rememberKanji();render()}
function changeKanjiPage(number){kanjiState.page=number;rememberKanji();refreshKanjiResults();document.getElementById('kanji-results').scrollIntoView({block:'start',behavior:'instant'})}
function clearKanjiFilters(){kanjiState.q='';kanjiState.category='all';kanjiState.source='all';kanjiState.scope='all';kanjiState.page=1;rememberKanji();render();document.getElementById('kanji-search').focus()}
function refreshKanjiResults(){const el=document.getElementById('kanji-results');if(el)el.innerHTML=kanjiResultHTML()}
function kanjiScreen(){if(kanjiState.view==='detail')return kanjiDetail();return title('Kanji','Kenali bentuknya, temukan maknanya.')+`<div class="kanji-library"><section class="kanji-intro"><div><span class="mini-tag">${prefs.level==='N4'?'N4 · MATERI LANJUTAN':'N5 · LANGKAH DASAR'}</span><h2>Satu karakter, banyak cerita.</h2><p>${prefs.level==='N4'?`${KANJI_N4_DATA.filter(k=>k.scope==='a2').length} kanji lanjutan A2, dengan ${KANJI_N4_DATA.filter(k=>k.scope==='a2-b1').length} pengayaan A2/B1 terpisah. Kanji N5 tidak diulang.`:'115 kanji dasar untuk mengenali bacaan, makna, dan contoh penggunaannya.'}</p></div><span lang="ja">漢</span></section><div class="kanji-toolbar"><label class="kanji-search-label" for="kanji-search">Cari kanji</label><div class="kanji-searchbox"><span aria-hidden="true">⌕</span><input type="search" id="kanji-search" autocomplete="off" maxlength="100" value="${esc(kanjiState.q)}" placeholder="Kanji, kana, romaji, arti, English…" oninput="kanjiSearchChange(this.value)"></div><div class="kanji-selects"><label>Kategori<select aria-label="Kategori kanji" onchange="kanjiFilter('category',this.value)"><option value="all">Semua kategori</option>${kanjiCategories().map(c=>`<option value="${c.id}" ${kanjiState.category===c.id?'selected':''}>${c.name} (${kanjiVisibleEntries().filter(k=>k.category===c.id).length})</option>`).join('')}</select></label>${prefs.level==='N4'?`<label>Cakupan<select aria-label="Cakupan kanji" onchange="kanjiFilter('scope',this.value)"><option value="all">Semua materi</option><option value="a2" ${kanjiState.scope==='a2'?'selected':''}>Lanjutan A2</option><option value="custom" ${kanjiState.scope==='custom'?'selected':''}>Buatanmu</option><option value="a2-b1" ${kanjiState.scope==='a2-b1'?'selected':''}>Pengayaan A2/B1</option></select></label>`:''}</div><p class="kanji-search-hint">Pencarian mencakup semua halaman dalam kategori yang dipilih.</p></div><div id="kanji-results" aria-live="polite" aria-atomic="false">${kanjiResultHTML()}</div></div>`}
function kanjiResultHTML(){const results=findKanji(kanjiState.q,kanjiState.category,kanjiState.source,prefs.level,kanjiState.scope),p=kanjiPageSlice(results,kanjiState.page);kanjiState.page=p.page;if(!p.total)return `<div class="kanji-empty"><span>🌱</span><h2>Belum menemukan kanjinya</h2><p>Coba kata lain, misalnya “air”, “mizu”, “みず”, atau “water”. Kamu juga bisa menghapus filter.</p><button class="primary" onclick="clearKanjiFilters()">Hapus pencarian & filter</button></div>`;const start=(p.page-1)*15+1,end=Math.min(p.page*15,p.total);let numbers=[];for(let n=Math.max(1,p.page-2);n<=Math.min(p.totalPages,p.page+2);n++)numbers.push(n);return `<div class="kanji-result-head"><h2>${kanjiState.category==='all'?'Kumpulan kanji':kanjiLabel(kanjiState.category)}</h2><span>${start}–${end} dari ${p.total}</span></div><div class="kanji-grid">${p.items.map(k=>`<button class="kanji-card" onclick="openKanji('${k.id}')" aria-label="${esc(k.char)}: ${esc(k.meaning)}"><span class="kanji-card-tag ${k.source.id==='jft-pdf'?'supplement':''}">${k.source.id==='custom'?'Buatanmu':k.level==='N4'?(k.scope==='a2-b1'?'A2/B1':'Lanjutan'):k.source.id==='jft-pdf'?'Tambahan':'Dasar'}</span><strong lang="ja">${esc(k.char)}</strong><span class="kanji-card-meaning">${esc(k.meaning.split(';')[0])}</span><span class="kanji-card-reading" lang="ja">${(k.kun[0]||k.on[0]||'').replaceAll('.','')}</span><span class="kanji-card-arrow" aria-hidden="true">↗</span></button>`).join('')}</div><nav class="kanji-pagination" aria-label="Halaman kanji"><button aria-label="Halaman sebelumnya" ${p.page===1?'disabled':''} onclick="changeKanjiPage(${p.page-1})">‹</button>${p.page>3?'<span>…</span>':''}${numbers.map(n=>`<button ${n===p.page?'aria-current="page" class="current"':''} aria-label="Halaman ${n}" onclick="changeKanjiPage(${n})">${n}</button>`).join('')}${p.page<p.totalPages-2?'<span>…</span>':''}<button aria-label="Halaman berikutnya" ${p.page===p.totalPages?'disabled':''} onclick="changeKanjiPage(${p.page+1})">›</button></nav><p class="kanji-page-caption">Halaman ${p.page} / ${p.totalPages} · Maksimal 15 kanji per halaman</p>`}
function kanjiReadingItem(r){const romaji=kanjiRomanize(r)+(/[っッ]$/.test(r)?' + konsonan rangkap':'');return `<div class="kanji-reading"><span lang="ja">${esc(r.replaceAll('.','・'))}</span><small>${esc(romaji)}</small></div>`}
function kanjiReadingColumn(label,readings,fold=false){const primary=fold?readings.slice(0,3):readings,other=fold?readings.slice(3):[];return `<div class="kanji-reading-column"><h3>${label}</h3>${readings.length?primary.map(kanjiReadingItem).join(''):'<p class="kanji-reading-none" aria-label="Tidak ada bacaan yang dicantumkan">—</p>'}${other.length?`<details class="kanji-extra-readings"><summary>Bacaan lain (${other.length})</summary>${other.map(kanjiReadingItem).join('')}</details>`:''}</div>`}
function kanjiDetail(){const k=kanjiEntries().find(k=>k.id===kanjiState.id);if(!k){kanjiState.view='list';return kanjiScreen()}const radicalForms={'人':'人 / 亻','示':'示 / 礻','艸':'艸 / 艹','辵':'辵 / 辶','巛':'巛 / 川','水':'水 / 氵','火':'火 / 灬','手':'手 / 扌','心':'心 / 忄','衣':'衣 / 衤','阜':'阜 / 阝','邑':'邑 / 阝','网':'网 / 罒','爪':'爪 / 爫','靑':'青 / 靑','黑':'黒 / 黑','戶':'戸 / 戶','毋':'毋 / 母'};return `<div class="kanji-detail"><div class="page-header"><button class="back" onclick="appBack()" aria-label="Kembali ke daftar kanji">‹</button><div><div class="eyebrow">${kanjiLabel(k.category)}</div><h1>Kenali ${esc(k.char)}</h1></div><span class="kanji-detail-level">${k.source.id==='custom'?'Buatanmu':k.level==='N4'?(k.scope==='a2-b1'?'Pengayaan A2/B1':'N4 · Lanjutan'):k.source.id==='jft-pdf'?'Tambahan dasar':'N5 · Dasar'}</span></div><section class="kanji-detail-hero"><div class="kanji-big" lang="ja">${esc(k.char)}</div><div><span class="eyebrow">ARTI & MAKNA</span><h2>${esc(k.meaning)}</h2>${k.english?`<p>${esc(k.english)}</p>`:''}</div></section><div class="kanji-divider"><span></span></div><section><div class="eyebrow">CARA BACA</div><h2 class="kanji-section-title">Bacaan utama</h2><div class="kanji-readings">${kanjiReadingColumn('On’yomi',k.on,true)}${kanjiReadingColumn('Kun’yomi',k.kun,true)}</div>${k.strokes||k.radical?`<div class="kanji-facts">${k.radical?`<span>Radikal <strong lang="ja">${esc(radicalForms[k.radical]||k.radical)}</strong></span>`:''}${k.strokes?`<span><strong>${k.strokes}</strong> guratan</span>`:''}</div>`:''}<p class="kanji-reading-help">Tanda ・ memisahkan bagian kanji dan akhiran kana. Bacaan dapat berubah ketika digabung menjadi kata. Tanda - menandai bacaan terikat; ッ di akhir menandai konsonan rangkap saat digabung. Bacaan tambahan dapat jarang dipakai.</p></section><div class="kanji-divider"><span></span></div>${k.mnemonic?`<section><div class="eyebrow">CARA MENGINGAT</div><h2 class="kanji-section-title">Jembatan ingatan</h2><p class="kanji-mnemonic">${esc(k.mnemonic)}</p><small class="kanji-mnemonic-note">Bantuan ingatan visual, bukan penjelasan asal-usul historis kanji.</small></section><div class="kanji-divider"><span></span></div>`:''}<section><div class="eyebrow">KATA YANG MEMAKAINYA</div><h2 class="kanji-section-title">Contoh kata</h2><div class="kanji-examples">${!k.examples.length?'<p class="hint">Belum ada contoh kata. Kamu bisa menambahkannya melalui Tambah data.</p>':''}${(k.examples.length?k.examples:[]).map(e=>`<div class="kanji-example"><strong lang="ja">${esc(e.word)}</strong><div><span lang="ja">${esc(e.kana)}</span><small>${esc(kanjiRomanize(e.kana))}</small><b>${esc(e.meaning)}</b></div><button class="round" onclick="speak(${esc(JSON.stringify(e.kana.replaceAll(' / ','、')))})" aria-label="Dengarkan ${esc(e.word)}">♪</button></div>`).join('')}</div></section><button class="kana-back-bottom" onclick="appBack()">‹ Kembali ke daftar kanji</button></div>`}
